import sys

def get_days_in_month(month, year):
    if month in [1, 3, 5, 7, 8, 10, 12]:
        return 31
    elif month in [4, 6, 9, 11]:
        return 30
    else:
        return 28

def count_occurrences(prophesy, d, m, y):
    target = f"{d:02d}-{m:02d}-{y}"
    count = 0
    i = 0
    n = len(prophesy)
    while i <= n - 10:
        if prophesy[i:i+10] == target:
            count += 1
            i += 1
        else:
            i += 1
    return count

def main():
    prophesy = sys.stdin.read().strip()

    max_count = -1
    best_date = None

    for year in range(2013, 2016):
        for month in range(1, 13):
            days = get_days_in_month(month, year)
            for day in range(1, days + 1):
                count = count_occurrences(prophesy, day, month, year)
                if count > max_count:
                    max_count = count
                    best_date = (day, month, year)

    if best_date:
        d, m, y = best_date
        print(f"{d:02d}-{m:02d}-{y}")

if __name__ == "__main__":
    main()
